WITH RankedPosts AS (SELECT p.Id, p.Title, p.CreationDate, p.OwnerUserId, COUNT(c.Id) AS CommentCount, RANK() OVER (PARTITION BY p.OwnerUserId ORDER BY p.CreationDate DESC NULLS FIRST) AS OwnerRank FROM Posts AS p LEFT JOIN Comments AS c ON p.Id = c.PostId WHERE p.CreationDate >= CAST('2024-10-01 12:34:56' AS Nullable(DateTime)) - INTERVAL '1' YEAR GROUP BY p.Id, p.Title, p.CreationDate, p.OwnerUserId), UserBadges AS (SELECT u.Id AS UserId, COUNT(b.Id) AS BadgeCount, SUM(CASE WHEN b.Class = 1 THEN 1 ELSE 0 END) AS GoldBadges, SUM(CASE WHEN b.Class = 2 THEN 1 ELSE 0 END) AS SilverBadges, SUM(CASE WHEN b.Class = 3 THEN 1 ELSE 0 END) AS BronzeBadges FROM Users AS u LEFT JOIN Badges AS b ON u.Id = b.UserId GROUP BY u.Id) SELECT up.DisplayName, up.Reputation, rp.Title AS RecentPostTitle, rp.CreationDate AS PostCreationDate, ub.BadgeCount, ub.GoldBadges, ub.SilverBadges, ub.BronzeBadges, CASE WHEN rp.CommentCount > 0 THEN 'Has Comments' WHEN rp.OwnerRank = 1 THEN 'Latest Post' ELSE 'No Comments' END AS PostStatus, COALESCE(vs.VoteType, 'No Votes') AS VoteStatus FROM RankedPosts AS rp JOIN Users AS up ON rp.OwnerUserId = up.Id LEFT JOIN UserBadges AS ub ON up.Id = ub.UserId LEFT JOIN (SELECT PostId, GROUP_CONCAT(CASE WHEN VoteTypeId = 2 THEN 'Upvote' WHEN VoteTypeId = 3 THEN 'Downvote' ELSE 'Other Vote' END, ', ') AS VoteType FROM Votes GROUP BY PostId) AS vs ON rp.Id = vs.PostId WHERE ub.BadgeCount > 0 ORDER BY up.Reputation DESC NULLS FIRST, rp.CreationDate DESC NULLS FIRST FETCH FIRST 10 ROWS ONLY